// The service worker (generated by vite.config.ts → sw.js) keeps the game's files on this device: the second
// visit starts from the phone or computer instead of the network, and works offline. This registers it and
// reports what is stored. Production builds only (the dev server serves fresh files); `?nosw` skips it.

const BASE = import.meta.env.BASE_URL
const wanted = import.meta.env.PROD && typeof navigator !== 'undefined' && 'serviceWorker' in navigator && !new URLSearchParams(location.search).has('nosw')

/** The registration (or null without a service worker). Started as early as the page runs. */
export const swRegistration: Promise<ServiceWorkerRegistration | null> = wanted
  ? navigator.serviceWorker.register(`${BASE}sw.js`, { scope: BASE }).catch((e) => {
      console.warn('[sw] not registered', e)
      return null
    })
  : Promise.resolve(null)

/** Resolves once the service worker controls this page (on a first visit it takes over a moment after the page starts), or after `timeoutMs`. */
export async function swControlling(timeoutMs: number): Promise<boolean> {
  if (!wanted) return false
  if (navigator.serviceWorker.controller) return true
  const reg = await Promise.race([swRegistration, new Promise<null>((r) => setTimeout(() => r(null), timeoutMs))])
  if (!reg) return false
  if (navigator.serviceWorker.controller) return true
  return new Promise((resolve) => {
    const t = setTimeout(() => resolve(!!navigator.serviceWorker.controller), timeoutMs)
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      clearTimeout(t)
      resolve(true)
    })
  })
}

export interface StorageInfo {
  usage: number // bytes this site keeps (game files, saves…)
  quota: number
  persisted: boolean // the browser will not clear it to free space
}

export async function storageInfo(): Promise<StorageInfo | null> {
  try {
    const est = await navigator.storage?.estimate?.()
    if (!est) return null
    return { usage: est.usage ?? 0, quota: est.quota ?? 0, persisted: (await navigator.storage.persisted?.()) ?? false }
  } catch {
    return null
  }
}

/**
 * Asks the browser to keep this site's storage (game files and saves) when space runs low. Call from a tap or
 * click. `quiet`: only where the browser decides by itself (Chrome, Edge, Safari) — Firefox would ask the player.
 */
export async function persistStorage(quiet = false): Promise<boolean> {
  try {
    if (quiet && /Firefox\//.test(navigator.userAgent)) return false
    if (await navigator.storage?.persisted?.()) return true
    return (await navigator.storage?.persist?.()) ?? false
  } catch {
    return false
  }
}

/** Deletes the downloaded game files kept on this device (saves stay). The next start downloads them again. */
export async function clearGameFiles() {
  try {
    for (const name of await caches.keys()) if (name.startsWith('home-')) await caches.delete(name)
  } catch {
    /* no cache storage */
  }
}
